import{_ as p,a0 as s,w as o,s as m,ao as i,I as n,a1 as a,A as r,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"elementary OS 7 安裝指南（附截圖） | LCTT x X-CMD","titleTemplate":false,"description":"elementary OS 7 安裝指南（附截圖） | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"elementary OS 7 安裝指南（附截圖） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"elementary OS 7 安裝指南（附截圖） | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20230206.0 ⭐️ Elementary OS 7 Installation Guide with Screenshots","title":"elementary OS 7 安裝指南（附截圖）","tag":"202302","desc":""},"relativePath":"202302/20230206.0 ⭐️ Elementary OS 7 Installation Guide with Screenshots.md","filePath":"[post].md"}'),u={name:"202302/20230206.0 ⭐️ Elementary OS 7 Installation Guide with Screenshots.md"};function d(b,t,y,w,h,g){const l=s("Link");return o(),m("div",null,[t[17]||(t[17]=i('<h1 id="elementary-os-7-安裝指南-附截圖" tabindex="-1">elementary OS 7 安裝指南（附截圖） <a class="header-anchor" href="#elementary-os-7-安裝指南-附截圖" aria-label="Permalink to “elementary OS 7 安裝指南（附截圖）”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/19/143743asfmbfrt7mc1tczb.jpg" alt=""></p><p>在這篇文章中，我們將介紹如何在筆記本電腦或台式機上一步一步地安裝 elementary OS 7，並附有截圖。它基於最新和穩定的 Ubuntu 22.04 LTS。</p><p>elementary OS 7 的代號為 “Horus”，並帶來了很多改進，例如：</p><ul><li>改進了 AppCenter 和安裝所有需要的應用。</li><li>改進了側載和可選商店（Flathub）的體驗。</li><li>最新的 GNOME Web 43，支持創建網絡應用。</li><li>快速獲得操作系統和應用的更新</li><li>電源配置文件管理</li><li>應用描述的改進</li></ul><h3 id="elementary-os-7-的系統要求" tabindex="-1">elementary OS 7 的系統要求 <a class="header-anchor" href="#elementary-os-7-的系統要求" aria-label="Permalink to “elementary OS 7 的系統要求”">​</a></h3><ul><li>雙核 64 位處理器</li><li>4GB 內存或更多</li><li>32GB 硬盤</li><li>互聯網接入</li><li>可啓動的 USB 驅動器（4GB 存儲空間）</li></ul><p>閒話少説，讓我們進入安裝步驟：</p><h3 id="_1-下載-elementary-os-7" tabindex="-1">1）下載 elementary OS 7 <a class="header-anchor" href="#_1-下載-elementary-os-7" aria-label="Permalink to “1）下載 elementary OS 7”">​</a></h3><p>使用下面的官方網址來下載 ISO 文件。</p>',10)),n("blockquote",null,[n("p",null,[n("strong",null,[a(l,{href:"https://elementary.io/"},{default:r(()=>[...t[0]||(t[0]=[e("下載 elementary OS 7 ISO",-1)])]),_:1})])])]),t[18]||(t[18]=n("p",null,"ISO 文件下載完成後，將其刻錄到 USB 驅動器，並使其可啓動。",-1)),t[19]||(t[19]=n("p",null,"在 Windows 操作系統中，用 Rufus 製作可啓動的 USB 驅動器。在 Linux 中，請參考以下網址：",-1)),n("blockquote",null,[n("p",null,[n("strong",null,[a(l,{href:"https://www.linuxtechi.com/create-bootable-usb-disk-dvd-ubuntu-linux-mint/"},{default:r(()=>[...t[1]||(t[1]=[e("如何在 Ubuntu/Linux Mint 上創建可啓動的 USB 驅動器",-1)])]),_:1})])])]),t[20]||(t[20]=i('<h3 id="_2-用可啓動介質啓動系統" tabindex="-1">2）用可啓動介質啓動系統 <a class="header-anchor" href="#_2-用可啓動介質啓動系統" aria-label="Permalink to “2）用可啓動介質啓動系統”">​</a></h3><p>現在用可啓動的 USB 驅動器啓動目標系統。從 BIOS 設置中把啓動介質從硬盤改為 USB。當系統用 USB 驅動器啓動時，我們將看到以下頁面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/BootScreen-elementaryOS7.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h3 id="_3-選擇安裝語言" tabindex="-1">3）選擇安裝語言 <a class="header-anchor" href="#_3-選擇安裝語言" aria-label="Permalink to “3）選擇安裝語言”">​</a></h3><p>選擇你喜歡的語言，然後點擊“<ruby>選擇<rt>Select</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Keyboard-Layout-ElementaryOS7-Installation.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h3 id="_4-選擇鍵盤佈局" tabindex="-1">4）選擇鍵盤佈局 <a class="header-anchor" href="#_4-選擇鍵盤佈局" aria-label="Permalink to “4）選擇鍵盤佈局”">​</a></h3><p>在這一步，你將被要求選擇鍵盤佈局，然後點擊“<ruby>選擇<rt>Select</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Keyboard-Layout-ElementaryOS7-Installation.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h3 id="_5-嘗試或安裝-elementary-os" tabindex="-1">5）嘗試或安裝 elementary OS <a class="header-anchor" href="#_5-嘗試或安裝-elementary-os" aria-label="Permalink to “5）嘗試或安裝 elementary OS”">​</a></h3><p>我們將看到下面的頁面，在這裏我們必須選擇安裝類型。它給了我們以下選項：</p><ul><li><ruby>試用演示模式<rt>Try Demo Mode</rt></ruby> – 試用 elementary OS 7 而不安裝</li><li><ruby>擦除磁盤並安裝<rt>Erase disk and Install</rt></ruby> – 安裝程序將擦除整個磁盤並自動創建所需分區。</li><li><ruby>自定義安裝（高級）<rt>Custom Install (Advanced)</rt></ruby> – 它將給我們一個選項來創建自定義分區。</li></ul><p>在這篇文章中，我將使用第二個選項（擦除磁盤並安裝）。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Installation-Type-ElementaryOS7.png?ezimgfmt=ngcb22/notWebP" alt=""></p><p>點擊“<ruby>擦除磁盤並安裝<rt>Erase disk and Install</rt></ruby>”。</p><p>在下面的屏幕上，選擇要安裝操作系統的驅動器，然後點擊“<ruby>擦除並安裝<rt>Erase and Install</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Select-Drive-for-elementaryOS7-Installation.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>如果你想對設備的驅動器進行加密，那麼點擊“<ruby>選擇密碼<rt>Choose Password</rt></ruby>”，否則點擊“<ruby>不加密<rt>Don’t Encrypt</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Encryption-Drive-ElementaryOS7-Installation.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h3 id="_6-安裝進度" tabindex="-1">6）安裝進度 <a class="header-anchor" href="#_6-安裝進度" aria-label="Permalink to “6）安裝進度”">​</a></h3><p>正如我們在下面看到的，安裝已經開始，並且正在進行中。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/ElementaryOS7-Installation-Progress.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>安裝完成後，安裝程序將提示重啓系統。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Restart-Device-After-elementaryOS7-Installation.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>點擊“<ruby>重啓設備<rt>Restart Device</rt></ruby>”，不要忘記從 BIOS 設置中改變啓動介質，以便用磁盤啓動。</p><h3 id="_7-創建本地用户並設置主機名" tabindex="-1">7）創建本地用户並設置主機名 <a class="header-anchor" href="#_7-創建本地用户並設置主機名" aria-label="Permalink to “7）創建本地用户並設置主機名”">​</a></h3><p>當系統在安裝後啓動時，系統會提示你輸入本地用户的詳細信息和系統的主機名。</p><p>根據你的要求指定這些細節。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Create-Local-Account-ElementaryOS7.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>點擊“<ruby>完成設置<rt>Finish Setup</rt></ruby>”。</p><p>在下面的頁面中，你將被提示輸入你在上面創建的本地用户憑證。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Login-screen-elementaryos7.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>輸入憑證後，點擊回車。</p><h3 id="_8-elementary-os-7-歡迎頁" tabindex="-1">8）elementary OS 7 歡迎頁 <a class="header-anchor" href="#_8-elementary-os-7-歡迎頁" aria-label="Permalink to “8）elementary OS 7 歡迎頁”">​</a></h3><p>我們將看到下面的歡迎頁。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/ElementaryOS7-Welcome-Screen.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>選擇“<ruby>跳過所有<rt>Skip All</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Get-Started-ElementaryOS7.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>點擊“<ruby>開始使用<rt>Get Started</rt></ruby>”，然後我們會看到下面的桌面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Desktop-Screen-ElementaryOS7-After-Installation.png" alt=""></p><p>很好，這表明你已經成功地在系統上安裝了 elementary OS 7。這就是本指南的全部內容，請探索這個令人興奮的 Linux 發行版並享受其中的樂趣吧😊。</p><hr>',42)),n("p",null,[t[3]||(t[3]=e("via: ",-1)),a(l,{href:"https://www.linuxtechi.com/elementary-os-7-installation-guide/"},{default:r(()=>[...t[2]||(t[2]=[e("https://www.linuxtechi.com/elementary-os-7-installation-guide/",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("作者：",-1)),a(l,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:r(()=>[...t[4]||(t[4]=[e("Pradeep Kumar",-1)])]),_:1}),t[9]||(t[9]=e(" 選題：",-1)),a(l,{href:"https://github.com/lkxed"},{default:r(()=>[...t[5]||(t[5]=[e("lkxed",-1)])]),_:1}),t[10]||(t[10]=e(" 譯者：",-1)),a(l,{href:"https://github.com/geekpi"},{default:r(()=>[...t[6]||(t[6]=[e("geekpi",-1)])]),_:1}),t[11]||(t[11]=e(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[12]||(t[12]=[e("LCTT",-1)])]),_:1}),t[15]||(t[15]=e(" 原創編譯，",-1)),a(l,{href:"https://linux.cn/"},{default:r(()=>[...t[13]||(t[13]=[e("Linux中國",-1)])]),_:1}),t[16]||(t[16]=e(" 榮譽推出",-1))])])}const x=p(u,[["render",d]]);export{f as __pageData,x as default};
